// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    SignatureMaker maker;
    FakeToken token;

    function setUp() public { c = new PuttyV2("", 0, address(this)); maker = new SignatureMaker(); token = new FakeToken(); }

    function testFuzz_property(uint256 premium, uint256 duration, uint256 nonce, uint256 warpTime) public {
        premium = bound(premium, 0, 1e30);
        duration = bound(duration, 1, 10_000 days - 1);
        vm.warp(bound(warpTime, 1, 2 ** 64 - 1));

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(maker),
            isCall: true,
            isLong: true,
            baseAsset: address(token),
            strike: 0,
            premium: premium,
            duration: duration,
            expiration: block.timestamp + 1,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes32 orderHash = c.hashOrder(order);
        uint256[] memory floorAssetTokenIds = new uint256[](0);

        vm.prank(address(0xb0b));
        uint256 positionId = c.fillOrder(order, "", floorAssetTokenIds);

        // General rule: for any filled long order, the recorded position expiration
        // must equal the fill time plus the order duration.
        assertTrue(
            c.positionExpirations(uint256(orderHash)) == block.timestamp + duration,
            "position expiration must be fill time plus duration"
        );
    }
}

contract SignatureMaker {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return 0x1626ba7e;
    }
}

contract FakeToken {
    function approve(address, uint256) external pure returns (bool) { return true; }
    function transfer(address, uint256) external pure returns (bool) { return true; }
    function transferFrom(address, address, uint256) external pure returns (bool) { return true; }
}
